package com.groupitemtracker;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import static com.groupitemtracker.GroupItemTrackerConfig.BankHighlightMode;

public class BankInterfaceManager extends WidgetItemOverlay
{
	private static final String BANK_SEARCH_KEYWORD = "/g";
	private static final String BANK_SEARCH_KEYWORD_HINT = "<br>" + "Type " + BANK_SEARCH_KEYWORD + " to show tracked items";
	private static final String MENU_OPTION_ADD = "Start-tracking";
	private static final String MENU_OPTION_REMOVE = "Stop-tracking";
	private static final String MENU_OPTION_EDIT_MODE_ENTER = "Enter edit mode";
	private static final String MENU_OPTION_EDIT_MODE_EXIT = "Exit edit mode";

	private final Client client;
	private final ConfigManager configManager;
	private final ItemIdentifier itemIdentifier;
	private final ItemManager itemManager;
	private final ItemTracker itemTracker;

	private Set<Integer> itemCache = new HashSet<>();
	private BankHighlightMode outlineMode = BankHighlightMode.NEVER;
	private Color outlineColor = new Color(0, 0, 0, 0);
	private boolean useSearchFilter = false;
	private boolean editModeEnabled = false;

	@Inject
	public BankInterfaceManager(Client client, ConfigManager configManager, ItemIdentifier itemIdentifier, ItemManager itemManager, ItemTracker itemTracker)
	{
		this.client = client;
		this.configManager = configManager;
		this.itemIdentifier = itemIdentifier;
		this.itemManager = itemManager;
		this.itemTracker = itemTracker;
		showOnBank();
	}

	public void refreshConfig(GroupItemTrackerConfig config)
	{
		useSearchFilter = config.useBankFilter();
		outlineMode = config.bankOutlineMode();
		outlineColor = config.bankOutlineColor();
		editModeEnabled = config.editModeActive();
	}

	public void freeExcessMemory()
	{
		itemCache = new HashSet<>(0);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		boolean drawOutlines = outlineMode == BankHighlightMode.ALWAYS || outlineMode == BankHighlightMode.EDIT_MODE_ONLY && editModeEnabled;
		if (drawOutlines && itemCache.contains(itemId))
		{
			Rectangle bounds = widgetItem.getCanvasBounds();
			BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), outlineColor);
			graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
		}
	}

	@Subscribe
	private void onInvalidated(ItemTracker.Invalidated event)
	{
		refreshItemCache();
	}

	@Subscribe
	private void onItemAdded(ItemTracker.ItemAdded event)
	{
		refreshItemCache();
	}

	@Subscribe
	private void onItemRemoved(ItemTracker.ItemRemoved event)
	{
		refreshItemCache();
	}

	@Subscribe
	private void onItemsUpdated(ItemTracker.ItemsUpdated event)
	{
		refreshItemCache();
	}

	@Subscribe
	private void onWidgetLoaded(WidgetLoaded event)
	{
		var interfaceID = event.getGroupId();
		if (interfaceID == InterfaceID.BANKMAIN || interfaceID == InterfaceID.SHARED_BANK)
		{
			refreshItemCache();
		}
	}

	private void refreshItemCache()
	{
		var bank = client.getItemContainer(InventoryID.BANK);
		if (bank != null)
		{
			itemCache.clear();
			addContainerToCache(bank);
			return;
		}

		var groupStorage = client.getItemContainer(InventoryID.INV_GROUP_TEMP);
		if (groupStorage != null)
		{
			itemCache.clear();
			addContainerToCache(groupStorage);

			// ItemTracker doesn't monitor group storage so we can't rely on its events to keep the cache up-to-date.
			// We can work around this by supplementing the cache with the tracked items in our inventory.
			// The cache is cleared whenever the bank is loaded, so we don't have to worry about reverting this.
			var inventory = client.getItemContainer(InventoryID.INV);
			if (inventory != null)
			{
				addContainerToCache(inventory);
			}
		}
	}

	private void addContainerToCache(ItemContainer container)
	{
		for (var item : container.getItems())
		{
			int itemID = item.getId();
			if (itemTracker.isTracking(itemID) && !itemIdentifier.isPlaceholder(itemID))
			{
				itemCache.add(itemID);
			}
		}
	}

	@Subscribe
	private void onMenuEntryAdded(MenuEntryAdded event)
	{
		boolean doToggleEditMode = false;
		boolean doToggleTrackedItem = false;

		switch (event.getActionParam1())
		{
			case InterfaceID.Bankmain.GIM_STORAGE:
				doToggleEditMode = event.getOption().equals("Group Storage");
				break;
			case InterfaceID.SharedBank.MAIN_BANK:
				doToggleEditMode = event.getOption().equals("Back to bank");
				break;
			case InterfaceID.Bankmain.ITEMS:
			case InterfaceID.SharedBank.ITEMS:
				doToggleTrackedItem = editModeEnabled && event.getOption().equals("Examine");
				break;
		}

		if (doToggleEditMode)
		{
			MenuEntry entry = client.getMenu().createMenuEntry(-1);
			entry.setOption(editModeEnabled ? MENU_OPTION_EDIT_MODE_EXIT : MENU_OPTION_EDIT_MODE_ENTER);
			entry.onClick(e -> configManager.setConfiguration(
				GroupItemTrackerConfig.GROUP, GroupItemTrackerConfig.KEY_EDIT_MODE_ACTIVE, !editModeEnabled));
		}

		if (doToggleTrackedItem)
		{
			final int itemID = event.getItemId();
			boolean isTracked = itemTracker.isTracking(itemID);
			MenuEntry entry = client.getMenu().createMenuEntry(-1);
			entry.setOption(isTracked ? MENU_OPTION_REMOVE : MENU_OPTION_ADD);
			entry.setTarget(event.getTarget());

			if (isTracked)
			{
				entry.onClick(e -> itemTracker.stopTracking(itemID));
			}
			else
			{
				entry.onClick(e -> itemTracker.startTracking(itemID));
			}
		}
	}

	@Subscribe(priority = -1) // Force callback to run after other plugins, specifically bank-tags.
	private void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!useSearchFilter)
		{
			return;
		}

		switch (event.getEventName())
		{
			case "setSearchBankInputText":
			case "setSearchBankInputTextFound":
			{
				// Append search filter hint.
				Object[] objectStack = client.getObjectStack();
				int lastIdx = client.getObjectStackSize() - 1;
				Object existingHint = objectStack[lastIdx];
				objectStack[lastIdx] = existingHint + BANK_SEARCH_KEYWORD_HINT;
				break;
			}
			case "bankSearchFilter":
			{
				// Filter search results by tracked items.
				Object lastObject = client.getObjectStack()[client.getObjectStackSize() - 1];
				if (lastObject.equals(BANK_SEARCH_KEYWORD))
				{
					int[] intStack = client.getIntStack();
					int intStackSize = client.getIntStackSize();
					int itemID = intStack[intStackSize - 1];

					int isSearchResult = !itemIdentifier.isPlaceholder(itemID) && itemTracker.isTracking(itemID) ? 1 : 0;
					intStack[intStackSize - 2] = isSearchResult;
				}
				break;
			}
		}
	}
}

package com.groupitemtracker;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(GroupItemTrackerConfig.GROUP)
public interface GroupItemTrackerConfig extends Config
{
	enum BankHighlightMode
	{
		NEVER,
		EDIT_MODE_ONLY,
		ALWAYS
	}

	String GROUP = "group-item-tracker";
	String KEY_BANK_FILTER = "bank-filter";
	String KEY_BANK_OUTLINE_MODE = "bank-outline-mode";
	String KEY_BANK_OUTLINE_COLOR = "bank-outline-color";
	String KEY_EDIT_MODE_ACTIVE = "edit_mode_active";
	String KEY_SHOW_SIDEBAR = "show-sidebar";
	String KEY_SIDEBAR_PRIORITY = "sidebar-priority";
	String KEY_SHOW_TUTORIAL = "sidebar-tutorial";


	@ConfigItem(
		keyName = KEY_EDIT_MODE_ACTIVE,
		name = "Edit mode",
		description = "Edit mode adds Start-tracking/Stop-tracking menu options for items in the bank and group storage.",
		position = 0)
	default boolean editModeActive()
	{
		return false;
	}

	@ConfigItem(
		keyName = KEY_SHOW_TUTORIAL,
		name = "Show tutorial",
		description = "Whether to show the tutorial panel in the sidebar.",
		position = 2)
	default boolean showTutorial()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_BANK_FILTER,
		name = "Search filter",
		description = "Type /g in the bank or group storage search interface to show all tracked items.",
		position = 1)
	default boolean useBankFilter()
	{
		return true;
	}

	@ConfigSection(
		name = "Tracked item outlines",
		description = "Configuration for drawing item outlines in the bank and group storage interfaces.",
		position = 20
	)
	String outlineSection = "outline";

	@ConfigItem(
		keyName = KEY_BANK_OUTLINE_MODE,
		name = "Outline mode",
		description = "When to draw outlines.",
		section = outlineSection)
	default BankHighlightMode bankOutlineMode()
	{
		return BankHighlightMode.EDIT_MODE_ONLY;
	}

	@ConfigItem(
		keyName = KEY_BANK_OUTLINE_COLOR,
		name = "Outline color",
		description = "The outline color.",
		section = outlineSection)
	default Color bankOutlineColor()
	{
		return Color.CYAN;
	}

	@ConfigSection(
		name = "Sidebar",
		description = "Configuration for sidebar visibility and order.",
		position = 10)
	String sidebarSection = "sidebar";

	@ConfigItem(
		keyName = KEY_SHOW_SIDEBAR,
		name = "Show sidebar",
		description = "Whether to show the sidebar.",
		section = sidebarSection,
		position = 0)
	default boolean showSidebar()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_SIDEBAR_PRIORITY,
		name = "Icon priority",
		description = "The order in which the sidebar icon appears. This is not a 1:1 mapping between number and order, and depends on the priority of other plugins.",
		section = sidebarSection,
		position = 1)
	default int sidebarPriority()
	{
		return 1;
	}
}

package com.groupitemtracker;

import com.google.inject.Provides;
import com.groupitemtracker.sidebar.SidebarPanel;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(name = "Group Item Tracker")
public class GroupItemTrackerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private GroupItemTrackerConfig config;

	@Inject
	private EventBus eventBus;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankInterfaceManager bankInterfaceManager;

	@Inject
	private ItemTracker itemTracker;

	@Inject
	private ProfileManager profileManager;

	@Inject
	private ConfigManager configManager;

	private NavigationButton navButton;
	private SidebarPanel sidebar;
	private BufferedImage sidebarIcon;
	private boolean isProfileLoaded;

	@Provides
	GroupItemTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GroupItemTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		sidebarIcon = ImageUtil.loadImageResource(getClass(), "sidebar_icon.png");
		if (config.showSidebar())
		{
			initSidebar();
		}

		overlayManager.add(bankInterfaceManager);
		eventBus.register(bankInterfaceManager);
		eventBus.register(itemTracker);

		clientThread.invokeLater(() ->
		{
			bankInterfaceManager.refreshConfig(config);
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadProfile();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		isProfileLoaded = false;
		sidebarIcon = null;
		tryDestroySidebar();

		overlayManager.remove(bankInterfaceManager);
		eventBus.unregister(bankInterfaceManager);
		eventBus.unregister(itemTracker);

		clientThread.invokeLater(() -> {
			bankInterfaceManager.freeExcessMemory();
			itemTracker.reset();
			itemTracker.freeExcessMemory();
		});
	}

	@Subscribe
	private void onGameStateChanged(GameStateChanged event)
	{
		if (isProfileLoaded && event.getGameState() == GameState.LOGIN_SCREEN)
		{
			itemTracker.reset();
			isProfileLoaded = false;
			if (sidebar != null)
			{
				sidebar.logout();
			}
		}
		else if (!isProfileLoaded && event.getGameState() == GameState.LOADING)
		{
			loadProfile();
		}
	}

	@Subscribe
	private void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(GroupItemTrackerConfig.GROUP))
		{
			return;
		}

		switch (event.getKey())
		{
			case GroupItemTrackerConfig.KEY_BANK_FILTER:
			case GroupItemTrackerConfig.KEY_BANK_OUTLINE_COLOR:
			case GroupItemTrackerConfig.KEY_BANK_OUTLINE_MODE:
			case GroupItemTrackerConfig.KEY_EDIT_MODE_ACTIVE:
				bankInterfaceManager.refreshConfig(config);
				break;
			case GroupItemTrackerConfig.KEY_SHOW_TUTORIAL:
			{
				if (sidebar != null)
				{
					sidebar.setTutorialPanelVisible(config.showTutorial());
				}
				break;
			}
			case GroupItemTrackerConfig.KEY_SIDEBAR_PRIORITY:
			{
				// This setting is likely to be tinkered with repeatedly, keep the sidebar to avoid unnecessary work.
				if (sidebar != null)
				{
					clientToolbar.removeNavigation(navButton);
					navButton = buildNavButton(sidebarIcon, sidebar, config.sidebarPriority());
					clientToolbar.addNavigation(navButton);
				}
				break;
			}
			case GroupItemTrackerConfig.KEY_SHOW_SIDEBAR:
			{
				// The user shouldn't incur the cost of something they aren't using, alloc/dealloc instead of hiding.
				// Parse value so that null == false, rather than null == config.showSidebar default value.
				// This prevents sidebar panel duplication upon resetting the config value.
				var showSidebar = Boolean.parseBoolean(event.getNewValue());
				if (showSidebar)
				{
					initSidebar();
					if (client.getGameState() == GameState.LOGGED_IN)
					{
						sidebar.loginAndSyncWithItemTracker();
					}
				}
				else
				{
					tryDestroySidebar();
				}
				break;
			}
		}
	}

	@Subscribe
	private void onItemAdded(ItemTracker.ItemAdded event)
	{
		int[] ids = itemTracker.exportItemIDs();
		profileManager.writeItemIDs(ids);
	}

	@Subscribe
	private void onItemRemoved(ItemTracker.ItemRemoved event)
	{
		int[] ids = itemTracker.exportItemIDs();
		profileManager.writeItemIDs(ids);
	}

	private void loadProfile()
	{
		int[] trackedItemIDs = profileManager.readItemIDs();
		itemTracker.loadItems(trackedItemIDs);
		isProfileLoaded = true;
		if (sidebar != null)
		{
			sidebar.login();
		}
	}

	private NavigationButton buildNavButton(BufferedImage icon, SidebarPanel panel, int priority)
	{
		return NavigationButton.builder()
			.tooltip("Group Item Tracker")
			.icon(icon)
			.panel(panel)
			.priority(priority)
			.build();
	}

	private void initSidebar()
	{
		sidebar = new SidebarPanel(configManager, profileManager, clientThread, itemManager, itemTracker, sidebarIcon);
		sidebar.setTutorialPanelVisible(config.showTutorial());
		eventBus.register(sidebar);
		navButton = buildNavButton(sidebarIcon, sidebar, config.sidebarPriority());
		clientToolbar.addNavigation(navButton);
	}

	private void tryDestroySidebar()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		if (sidebar != null)
		{
			eventBus.unregister(sidebar);
			sidebar = null;
		}
	}
}

package com.groupitemtracker;

import com.google.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

// Adapter for simple item composition queries and test mocks.
public class ItemIdentifier
{
	private final ItemManager itemManager;

	@Inject
	public ItemIdentifier(ItemManager manager)
	{
		this.itemManager = manager;
	}

	public String getName(int itemID)
	{
		return itemManager.getItemComposition(itemID)
			.getMembersName();
	}

	public boolean isPlaceholder(int itemID)
	{
		return itemManager.getItemComposition(itemID)
			.getPlaceholderTemplateId() != -1;
	}

	public int getBaseID(int itemID)
	{
		return ItemVariationMapping.map(
			itemManager.canonicalize(itemID));
	}
}

package com.groupitemtracker;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Data;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Singleton
public class ItemTracker
{
	@Data
	public static final class ItemAdded
	{
		private final TrackedItemSnapshot item;
	}

	@Data
	public static final class ItemRemoved
	{
		private final TrackedItemSnapshot item;
	}

	@Data
	public static final class ItemsUpdated
	{
		private final Collection<TrackedItemSnapshot> items;
	}

	@Data
	public static final class Invalidated
	{
		private final Collection<TrackedItemSnapshot> items;
	}

	public static final class SyncedWithBank
	{
		// Signal message, no data.
	}

	private final Client client;
	private final EventBus eventBus;
	private final ItemIdentifier identifier;
	private Map<Integer, TrackedItem> items = new HashMap<>();
	private Map<Integer, TrackedItemSnapshot> snapshots = new HashMap<>();
	private boolean bankClosedLastTick = false;
	private boolean sharedBankClosedLastTick = false;
	private boolean containerHasChanged = false;

	@Getter
	private boolean syncedWithBank = false;

	@Inject
	public ItemTracker(Client client, EventBus eventBus, ItemIdentifier identifier)
	{
		this.client = client;
		this.eventBus = eventBus;
		this.identifier = identifier;
	}

	public Collection<TrackedItemSnapshot> getItems()
	{
		return Collections.unmodifiableCollection(snapshots.values());
	}

	public int[] exportItemIDs()
	{
		var ids = new int[items.size()];
		int i = 0;

		for (var item : items.values())
		{
			ids[i] = item.realID;
			i++;
		}

		return ids;
	}

	public boolean isTracking(int id)
	{
		int baseID = identifier.getBaseID(id);
		return items.containsKey(baseID);
	}

	public void loadItems(int[] itemIDs)
	{
		resetState();

		for (int itemID : itemIDs)
		{
			int baseID = identifier.getBaseID(itemID);
			if (!items.containsKey(baseID))
			{
				items.put(baseID, new TrackedItem(baseID, itemID, identifier.getName(itemID)));
			}
		}

		for (var kind : TrackedContainer.values())
		{
			ItemContainer container = client.getItemContainer(kind.containerID);
			if (container != null)
			{
				refreshContainer(kind, container);
				if (!syncedWithBank && kind == TrackedContainer.BANK)
				{
					syncedWithBank = true;
					eventBus.post(new SyncedWithBank());
				}
			}
		}

		var outgoingSnapshots = new ArrayList<TrackedItemSnapshot>(items.size());
		for (TrackedItem item : items.values())
		{
			var snapshot = new TrackedItemSnapshot(item);
			outgoingSnapshots.add(snapshot);
			snapshots.put(item.baseID, snapshot);
		}

		eventBus.post(new Invalidated(Collections.unmodifiableCollection(outgoingSnapshots)));
	}

	public void startTracking(int itemID)
	{
		int baseID = identifier.getBaseID(itemID);
		if (items.containsKey(baseID))
		{
			return;
		}

		// Set initial item count for all available containers.
		var item = new TrackedItem(baseID, itemID, identifier.getName(itemID));
		for (var kind : TrackedContainer.values())
		{
			var container = client.getItemContainer(kind.containerID);
			if (container == null)
			{
				continue;
			}

			int count = 0;
			for (var containerItem : container.getItems())
			{
				int id = containerItem.getId();
				if (identifier.getBaseID(id) == baseID && !identifier.isPlaceholder(id))
				{
					count += containerItem.getQuantity();
				}
			}
			item.counters.put(kind, count);
		}

		items.put(baseID, item);
		var snapshot = new TrackedItemSnapshot(item);
		snapshots.put(baseID, snapshot);
		eventBus.post(new ItemAdded(snapshot));
	}

	public void stopTracking(int itemID)
	{
		int baseID = identifier.getBaseID(itemID);
		if (items.remove(baseID) != null)
		{
			TrackedItemSnapshot removedSnapshots = snapshots.remove(baseID);
			eventBus.post(new ItemRemoved(removedSnapshots));
		}
	}

	public void reset()
	{
		resetState();
		eventBus.post(new Invalidated(new ArrayList<>()));
	}

	public void freeExcessMemory()
	{
		items = new HashMap<>(0);
		snapshots = new HashMap<>(0);
	}

	@Subscribe
	private void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankClosedLastTick = true;
		}
		else if (event.getGroupId() == InterfaceID.SHARED_BANK)
		{
			sharedBankClosedLastTick = true;
		}
	}

	@Subscribe
	private void onItemContainerChanged(ItemContainerChanged event)
	{
		var kind = TrackedContainer.fromContainerID(event.getContainerId());
		if (kind != null)
		{
			refreshContainer(kind, event.getItemContainer());
			containerHasChanged = true;
			if (!syncedWithBank && kind == TrackedContainer.BANK)
			{
				syncedWithBank = true;
				eventBus.post(new SyncedWithBank());
			}
		}
	}

	@Subscribe
	private void onGameTick(GameTick event)
	{
		if (containerHasChanged)
		{
			// Don't allocate until we match a changed item.
			ArrayList<TrackedItemSnapshot> updatedSnapshots = null;

			for (TrackedItem item : items.values())
			{
				var snapshot = snapshots.get(item.baseID);
				if (snapshot.hasMatchingContainerCounts(item))
				{
					continue;
				}

				// Handle edge-case where transferring an item and closing the bank on the same tick caused counter desync.
				// e.g. Deposited item is decremented from inventory but not incremented in bank.
				// Note: Immediately closing the interface with ESC still incurs desync, can this be improved further?
				// Note: The adjustment isn't made if the shared bank was closed, as this results in further desync.
				if (bankClosedLastTick && !sharedBankClosedLastTick)
				{
					int prevTotal = snapshot.countAll();
					int currentTotal = item.countAll();
					int error = currentTotal - prevTotal;
					int corrected = item.counters.get(TrackedContainer.BANK) - error;
					item.counters.put(TrackedContainer.BANK, corrected);
				}

				snapshot = new TrackedItemSnapshot(item);
				snapshots.put(item.baseID, snapshot);

				if (updatedSnapshots == null)
				{
					// Big enough to avoid resize in most cases.
					updatedSnapshots = new ArrayList<>(8);
				}
				updatedSnapshots.add(snapshot);
			}

			if (updatedSnapshots != null)
			{
				eventBus.post(new ItemsUpdated(Collections.unmodifiableCollection(updatedSnapshots)));
			}
		}

		bankClosedLastTick = false;
		sharedBankClosedLastTick = false;
		containerHasChanged = false;
	}

	private void resetState()
	{
		bankClosedLastTick = false;
		sharedBankClosedLastTick = false;
		containerHasChanged = false;
		syncedWithBank = false;
		items.clear();
		snapshots.clear();
	}

	private void refreshContainer(TrackedContainer kind, ItemContainer container)
	{
		assert kind.containerID == container.getId();

		for (TrackedItem item : items.values())
		{
			item.counters.put(kind, 0);
		}

		for (Item containerItem : container.getItems())
		{
			int id = containerItem.getId();
			TrackedItem item = items.get(identifier.getBaseID(id));
			if (item != null && !identifier.isPlaceholder(id))
			{
				int count = item.counters.get(kind) + containerItem.getQuantity();
				item.counters.put(kind, count);
			}
		}
	}
}

package com.groupitemtracker;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

public class ProfileManager
{
	public static final String CONFIG_KEY_TRACKED_ITEMS = "tracked-items";
	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public ProfileManager(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public int[] readItemIDs()
	{
		String json = configManager.getRSProfileConfiguration(GroupItemTrackerConfig.GROUP, CONFIG_KEY_TRACKED_ITEMS);
		int[] ids = gson.fromJson(json, int[].class);
		return ids == null ? new int[0] : ids;
	}

	public String readItemIDsAsJson()
	{
		String json = configManager.getRSProfileConfiguration(GroupItemTrackerConfig.GROUP, CONFIG_KEY_TRACKED_ITEMS);
		return json == null ? "" : json;
	}

	public void writeItemIDs(int[] ids)
	{
		String json = gson.toJson(ids);
		configManager.setRSProfileConfiguration(GroupItemTrackerConfig.GROUP, CONFIG_KEY_TRACKED_ITEMS, json);
	}

	public boolean tryWriteItemIDsFromJson(String json)
	{
		try
		{
			var ids = gson.fromJson(json, int[].class);
			if (ids != null)
			{
				writeItemIDs(ids);
				return true;
			}
			// Failed.
		}
		catch (JsonSyntaxException ignored)
		{
			// Failed.
		}

		return false;
	}
}

package com.groupitemtracker;

import net.runelite.api.gameval.InventoryID;

public enum TrackedContainer
{
	BANK(InventoryID.BANK, "Bank"),
	EQUIPMENT(InventoryID.WORN, "Equipment"),
	INVENTORY(InventoryID.INV, "Inventory");

	public final int mask;
	public final int containerID;
	public final String description;

	TrackedContainer(int containerID, String description)
	{
		this.mask = 1 << ordinal();
		this.containerID = containerID;
		this.description = description;
	}

	public static TrackedContainer fromContainerID(int containerID)
	{
		for (var value : TrackedContainer.values())
		{
			if (value.containerID == containerID)
			{
				return value;
			}
		}

		return null;
	}
}

package com.groupitemtracker;

import java.util.EnumMap;

public class TrackedItem
{
	private static final EnumMap<TrackedContainer, Integer> EMPTY_COUNTERS;

	static
	{
		EMPTY_COUNTERS = new EnumMap<>(TrackedContainer.class);
		for (var kind : TrackedContainer.values())
		{
			EMPTY_COUNTERS.put(kind, 0);
		}
	}

	public final String name;
	public final int baseID;
	public final int realID;
	public final EnumMap<TrackedContainer, Integer> counters;

	public TrackedItem(int baseID, int realID, String name)
	{
		this.name = name;
		this.baseID = baseID;
		this.realID = realID;
		this.counters = new EnumMap<>(EMPTY_COUNTERS);
	}

	public int countAll()
	{
		int sum = 0;
		for (int count : counters.values())
		{
			sum += count;
		}

		return sum;
	}
}

package com.groupitemtracker;

public final class TrackedItemSnapshot
{
	public final String name;
	public final int itemID;
	public final int locationMask;
	public final int bankCount;
	public final int equipmentCount;
	public final int inventoryCount;

	public TrackedItemSnapshot(TrackedItem item)
	{
		this.name = item.name;
		this.itemID = item.realID;
		this.bankCount = item.counters.get(TrackedContainer.BANK);
		this.equipmentCount = item.counters.get(TrackedContainer.EQUIPMENT);
		this.inventoryCount = item.counters.get(TrackedContainer.INVENTORY);

		var mask = 0;
		mask |= bankCount > 0 ? TrackedContainer.BANK.mask : 0;
		mask |= equipmentCount > 0 ? TrackedContainer.EQUIPMENT.mask : 0;
		mask |= inventoryCount > 0 ? TrackedContainer.INVENTORY.mask : 0;
		this.locationMask = mask;
	}

	public int countAll()
	{
		return bankCount + equipmentCount + inventoryCount;
	}

	public boolean hasMatchingContainerCounts(TrackedItem item)
	{
		return bankCount == item.counters.get(TrackedContainer.BANK)
			&& equipmentCount == item.counters.get(TrackedContainer.EQUIPMENT)
			&& inventoryCount == item.counters.get(TrackedContainer.INVENTORY);
	}
}

